ssize_t readlinkat(int dirfd, const char *pathname,
                   char *buf, size_t bufsiz);

// dirfd: Directory FD for resolution; use AT_FDCWD for CWD.
// Return: Length of link target written, or -1 on error.

#define AT_FDCWD (-100)

char target[256];
ssize_t bytes_read;

// 1. Resolve relative to current working directory (like readlink())
bytes_read = readlinkat(AT_FDCWD, "my_link",
                        target, sizeof(target));

// 2. Resolve relative to directory descriptor 'config_fd'
int config_fd = /* initialized FD */;
bytes_read = readlinkat(config_fd, "data_link",
                        target, sizeof(target));

if (bytes_read != -1)
    target[bytes_read] = '\0';
